const [active, setActive] = useState(chats[0]);

function Panel() {
  const { setOpen } = usePanelside();

  return (
    <Panelside.Panel>
      <Panelside.Content>
        {chats.map((chat) => (
          <Panelside.Item
            key={chat}
            label={chat}
            active={chat === active}
            onPress={() => {
              setActive(chat);
              setOpen(false);
            }}
          />
        ))}
      </Panelside.Content>
    </Panelside.Panel>
  );
}

<Panelside haptics>
  <Panel />
  <Panelside.Scene>
    <Conversation title={active} />
  </Panelside.Scene>
</Panelside>
